// seed: tests/seed.spec.ts (гость) · прод, только чтение.
import { test, expect } from '@playwright/test';
import { prepareReadOnly, openCalculator, fillInputs, expectResult, SET1, DEVICES } from './calculator.helpers';

test.use({ serviceWorkers: 'block' });

test.describe('Калькулятор — формулы и крайние случаи', () => {
  for (const tag of DEVICES) {
    test(`Ползунок налога: пересчёт сразу, 27% по формуле, RTL ← увеличивает, End=50 Home=0 #80ff63 #d45b2a ${tag} @prod-safe`, async ({ page, context }) => {
      await prepareReadOnly(context);
      await openCalculator(page);
      await fillInputs(page, SET1);
      await expectResult(page, 'מס חודשי משוער', '5,750 ₪');

      const slider = page.getByRole('slider');
      await slider.focus();
      await page.keyboard.press('ArrowDown');
      await expect(slider).toHaveAttribute('aria-valuenow', '22');
      await expectResult(page, 'מס חודשי משוער', '5,500 ₪');

      // RTL: ← увеличивает.
      for (let i = 0; i < 5; i++) await page.keyboard.press('ArrowLeft');
      await expect(slider).toHaveAttribute('aria-valuenow', '27');
      await expectResult(page, 'מס חודשי משוער', '6,750 ₪');
      await expectResult(page, 'תזרים חודשי משוער', '13,250 ₪');
      await expectResult(page, 'תשואה שנתית על ההון העצמי', '39.8%');

      await page.keyboard.press('End');
      await expect(slider).toHaveAttribute('aria-valuenow', '50');
      await page.keyboard.press('Home');
      await expect(slider).toHaveAttribute('aria-valuenow', '0');
    });
  }
});
